from ta_ue_plugin_android.uepc.android_control import AndroidControl


def _get_public_method_names(obj):
    result = []
    for name in dir(obj):
        if name.startswith('_'):
            continue
        if callable(getattr(obj, name)):
            result.append(name)
    return result


# Android part:


def _create_android_specific_keywords_list():
    return _get_public_method_names(AndroidControl)


__android_specific_keywords_list = _create_android_specific_keywords_list()


def get_android_specific_keywords_list():
    """
    get_android_specific_keywords_list
    :return:
    """
    return __android_specific_keywords_list


# Qualcomm part:

def _create_qualcomm_at_specific_keywords_list():
    # to avoid problems with: ImportError: No module named serial.serialutil
    from ta_ue_plugin_android.ue.at_cmds_ue.at_cmds_ue_control import AtCmdsUeControl
    return _get_public_method_names(AtCmdsUeControl(None, None))


__qualcomm_at_specific_keywords_list = None


def get_qualcomm_at_specific_keywords_list():
    """
    get_qualcomm_at_specific_keywords_list
    :return:
    """
    global __qualcomm_at_specific_keywords_list  # pylint: disable=global-statement
    if __qualcomm_at_specific_keywords_list is None:
        __qualcomm_at_specific_keywords_list = _create_qualcomm_at_specific_keywords_list()
    return __qualcomm_at_specific_keywords_list


# SoundcardAndroid part

def _create_soundcard_android_specific_keywords_list():
    from ta_ue_plugin_android.ue.android.uepcsoundcard.soundcard_android_control import SoundcardAndroidControl
    return _get_public_method_names(SoundcardAndroidControl)


__soundcard_android_specific_keywords_list = None


def get_soundcard_android_specific_keywords_list():
    """
    get_soundcard_android_specific_keywords_list
    :return:
    """
    global __soundcard_android_specific_keywords_list  # pylint: disable=global-statement
    if __soundcard_android_specific_keywords_list is None:
        __soundcard_android_specific_keywords_list = _create_soundcard_android_specific_keywords_list()
    return __soundcard_android_specific_keywords_list
